+    const int32_t newest_position = old_count + accepted - 1;
+    for (int layer = tid; layer < num_layers; layer += blockDim.x) {
+      device_buffer_tokens[layer * token_layer_stride + rid * token_req_stride + HOT_BUFFER_SIZE] =
